(()=>{
let pending;
const installed=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
const button=document.createElement('button');button.type='button';button.textContent=installed()?'App installed · Help':'Install app';button.style.cssText='padding:8px 14px;border-radius:9px;white-space:nowrap';
const top=document.querySelector('.top');top.style.flexWrap='wrap';top.style.gap='10px';top.append(button);
const dialog=document.createElement('dialog');dialog.setAttribute('aria-labelledby','install-title');dialog.style.cssText='max-width:560px;width:calc(100% - 36px);border:1px solid #cbdcdb;border-radius:18px;padding:26px;color:#102e38;box-shadow:0 20px 80px #102e3840';
dialog.innerHTML=`<h2 id="install-title">FN Clinical — on your device</h2><p>Install this web app to open it from its own icon and window.</p><p><strong>iPhone / iPad</strong><br>Open this link in Safari → Share → Add to Home Screen → Add. If shown, keep “Open as Web App” enabled.</p><p><strong>Windows / laptop</strong><br>Open in Chrome or Edge. Use the install icon in the address bar or the browser menu → Install this app / Apps.</p><p><strong>Android</strong><br>Open in Chrome → menu → Install app / Add to Home screen.</p><p><strong>Connection & data</strong><br>The demo interface can be available offline after its first successful load. Shared visits, sign-in and team updates require internet. Device-local drafts do not automatically sync. External calls and notifications are not enabled.</p><p dir="rtl">على الآيفون: افتح الرابط في Safari ثم مشاركة ← إضافة إلى الشاشة الرئيسية. على اللابتوب: افتحه في Chrome أو Edge ثم تثبيت التطبيق.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><button id="install-native" hidden>Install now</button><button id="install-close">Close</button></div>`;
document.body.append(dialog);button.onclick=()=>dialog.showModal();dialog.querySelector('#install-close').onclick=()=>dialog.close();
const native=dialog.querySelector('#install-native');window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();pending=e;native.hidden=false});native.onclick=async()=>{if(!pending)return;const prompt=pending;pending=null;native.hidden=true;await prompt.prompt();await prompt.userChoice};window.addEventListener('appinstalled',()=>{pending=null;native.hidden=true;button.textContent='App installed · Help'});
const status=document.createElement('div');status.setAttribute('role','status');status.style.cssText='padding:10px 16px;background:#fff0ce;color:#684400;border-radius:8px;margin-bottom:12px';status.textContent='Offline — shared records and team updates are unavailable. Local demo data may be outdated.';top.after(status);const update=()=>status.hidden=navigator.onLine;addEventListener('online',update);addEventListener('offline',update);update();
})();
